from decimal import Decimal, ROUND_HALF_UP


_CENTS = Decimal("0.01")


def _numeric(value) -> Decimal:
    """Apply legacy NVL(..., 0) numeric behavior."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def recompute(order: dict, lines: list[dict]) -> tuple[dict, list[dict], list]:
    """
    Recompute live order-line extensions and the discounted order total.

    Returned dictionaries are copies; input dictionaries and list are not mutated.
    """
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    total = Decimal("0")

    for source_line, new_line in zip(lines, new_lines):
        if source_line.get("DEL_FLG") == "Y":
            continue

        ext = _cents(_numeric(source_line.get("QTY")) * _numeric(source_line.get("UNIT_PRC")))
        new_line["EXT_AMT"] = float(ext)
        total += ext

    discounted = _cents(
        total * (Decimal("100") - _numeric(order.get("DISC_PCT"))) / Decimal("100")
    )

    audits = []
    if _numeric(order.get("TOT_AMT")) != discounted:
        new_order["TOT_AMT"] = float(discounted)
        audits.append(("ORD_RETOTAL", order.get("ORD_ID")))
    else:
        new_order["TOT_AMT"] = float(discounted)

    return new_order, new_lines, audits
